        titulo: "F-250",
        preco: "160.000",
        imagem: "https://www.chavesnamao.com.br/imn/0000x0000/N/75/veiculos/99015/8042126/ford-f-250-em-belo-horizonte-mg-9c9dca5f.jpg"
